using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Mvc.ModelBinding;
using Microsoft.AspNetCore.Mvc.ModelBinding.Validation;

namespace NexusCommunication.Models;

/// <summary>
/// A payment received against a bill (at a retail outlet or at the accounts office).
/// The receipt number, payment date and receiving employee are set by the server.
/// </summary>
public class Payment
{
    public int Id { get; set; }

    /// <summary>Generated by the server (RCPT00000001 ...). Not validated because it is not typed by the user.</summary>
    [BindNever, ValidateNever]
    [MaxLength(20)] public string ReceiptNumber { get; set; } = "";

    [Range(1, int.MaxValue, ErrorMessage = "Please select a bill.")]
    public int BillId { get; set; }
    public Bill? Bill { get; set; }

    /// <summary>Amount received. Must be greater than zero (the upper limit is checked against the bill balance).</summary>
    [Range(0.01, 100000000.0, ErrorMessage = "Payment amount must be greater than zero.")]
    public decimal Amount { get; set; }

    [BindNever]
    public DateTime PaidOn { get; set; } = DateTime.UtcNow;

    [EnumDataType(typeof(PaymentMode), ErrorMessage = "Select a valid payment mode.")]
    [Display(Name = "Payment Mode")]
    public PaymentMode Mode { get; set; }

    /// <summary>Cheque number / card or online transaction reference.</summary>
    [MaxLength(100, ErrorMessage = "Reference cannot be longer than 100 characters.")]
    public string? Reference { get; set; }

    [BindNever]
    public int ReceivedByEmployeeId { get; set; }
}
